svg.script:
(function(){
var D=JSON.parse(document.getElementById('wxdata').textContent);
var fo=document.getElementById('fo'), pb=document.getElementById('pbody');
var lb=document.getElementById('lb'), lbi=document.getElementById('lbi');
function esc(s){return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;')}
function bindThumbs(){
  Array.prototype.forEach.call(pb.querySelectorAll('img'),function(im){
    im.style.cursor='zoom-in';
    im.addEventListener('click',function(e){e.stopPropagation();lbi.src=im.src;lb.style.display='';});
  });
}
Array.prototype.forEach.call(document.querySelectorAll('.pin'),function(g){
  g.addEventListener('click',function(){
    var d=D[+g.getAttribute('data-i')];
    /* 클릭한 핀을 패널이 가리지 않도록 반대쪽으로 붙인다 */
    var cx=+g.querySelector('circle').getAttribute('cx');
    fo.setAttribute('x',cx>1383/2?0:1383-340);
    var stars=d.imp?Array(d.imp+1).join('★'):'';
    pb.innerHTML='<div style="display:flex;align-items:center;gap:8px;margin-bottom:6px">'
      +'<span style="width:24px;height:24px;border-radius:50%;background:'+d.col+';color:#0b0d12;font-weight:700;display:inline-flex;align-items:center;justify-content:center;font-size:12px">'+d.n+'</span>'
      +(stars?'<span style="color:#fbbf24;font-size:14px">'+stars+'</span>':'')
      +'<b style="font-size:16px">'+esc(d.t)+'</b></div>'
      +'<div style="color:#8b93a3;font-size:11.5px;margin-bottom:10px">'+esc(d.c)+(d.h?' &#183; '+esc(d.h):'')+'</div>'
      +(d.d?'<div style="white-space:pre-wrap;margin-bottom:12px">'+esc(d.d)+'</div>':'<div style="color:#8b93a3;margin-bottom:12px">설명이 없습니다.</div>')
      +d.g.map(function(u){return '<img src="'+u+'" style="width:100%;border-radius:6px;margin-bottom:8px"/>'}).join('');
    bindThumbs();
    fo.style.display='';
  });
});
document.getElementById('cls').addEventListener('click',function(){fo.style.display='none'});
lb.addEventListener('click',function(){lb.style.display='none';lbi.src='';});
})();
